preConditionHook:
// Brooks's three-stage breakout pullback: a bar within the last few bars
// closed beyond a flag or range, the market then pulled back for one or more
// bars, and this bar closes above the highest high of that pullback -- buy
// the resumption at the next open. Short is the mirror on lows.
//
// Stage 1, the breakout bar. A bounded backward scan finds the MOST RECENT
// bar k in 1..maxBarsSinceBreakout whose close is beyond the extreme of the
// breakoutLookback bars ENDING ONE BAR BEFORE IT. The level is open-coded
// because Highest(High, breakoutLookback)[k + 1] is a history reference on a
// function call at a VARIABLE offset; Extremes(), which Highest and Lowest
// call, is EL source and is exactly this loop -- seed at the first bar of the
// window and scan the rest with a strict, tolerance-carrying comparison,
// hence el_gt / el_lt. "Most recent" is the brkUpBar == -1 guard rather than
// a loop break, because EasyLanguage has no break and the twins must run the
// same number of iterations.
//
// Stage 2, the pullback: its length is k - 1 bars, and it must lie between
// minPullbackBars and maxPullbackBars. The bound is on bar COUNT, not depth
// -- one source lets the pullback make a higher low and another a lower low,
// so depth cannot be the gate. At minPullbackBars = maxPullbackBars = 1 this
// is the cheapest mechanization in the sources.
//
// Stage 3, the resumption: close above the highest high of those pullback
// bars. That leg alone is CloseAbovePriorHighestHigh, but over a window whose
// LENGTH is data-dependent, so it cannot be split out as its own placement --
// which is why this is one rule and not two.
//
// The deepest bar touched is maxBarsSinceBreakout + breakoutLookback.
brkUpBar = -1;
brkDnBar = -1;
for (int k = 1; k <= (int)maxBarsSinceBreakout; ++k) {
    double lvlHigh = high[k + 1];
    double lvlLow = low[k + 1];
    for (int j = k + 2; j <= k + (int)breakoutLookback; ++j) {
        if (el_gt(high[j], lvlHigh)) lvlHigh = high[j];
        if (el_lt(low[j], lvlLow)) lvlLow = low[j];
    }
    if (brkUpBar == -1 && el_gt(close[k], lvlHigh)) brkUpBar = k;
    if (brkDnBar == -1 && el_lt(close[k], lvlLow)) brkDnBar = k;
}
pbUp = brkUpBar - 1;
pbDn = brkDnBar - 1;
okUp = brkUpBar != -1 && el_ge((double)pbUp, minPullbackBars) && el_le((double)pbUp, maxPullbackBars);
okDn = brkDnBar != -1 && el_ge((double)pbDn, minPullbackBars) && el_le((double)pbDn, maxPullbackBars);
pbHigh = high[1];
pbLow = low[1];
if (okUp) {
    for (int m = 2; m <= pbUp; ++m) {
        if (el_gt(high[m], pbHigh)) pbHigh = high[m];
    }
}
if (okDn) {
    for (int m = 2; m <= pbDn; ++m) {
        if (el_lt(low[m], pbLow)) pbLow = low[m];
    }
}
entryUp = okUp && el_gt(close[0], pbHigh);
entryDn = okDn && el_lt(close[0], pbLow);
